import assert from 'node:assert/strict';
import {promises as fs} from 'node:fs';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {performance} from 'node:perf_hooks';
import {probes} from './probes.mjs';

const [tree, label] = process.argv.slice(2);
const entry = pathToFileURL(path.join(tree, 'lib/index.js')).href;
const api = await import(entry);
const {readOrCopyLocalResource} = await import(pathToFileURL(path.join(tree,
  'lib/life-cycle/read-or-copy-local-resource.js')));
const root = await fs.mkdtemp(path.join(tmpdir(), 'short-repair-'));
const guard = path.join(root, 'guard.bin');
const results = [];
const samples = 2;
const documents = 6;
const readCount = 24;
const retryCount = 250000;
const bytes = Buffer.alloc(65536, 97);
const html = id => '<html><head><title>Fixture</title></head><body>' +
  `<p data-fixture="${id}">` + 'local input '.repeat(80) + '</p></body></html>';
let configId = 0;

async function observed(key, sample, run) {
  global.gc();
  const before = await probes(guard);
  const {verify, ...result} = await run();
  const after = await probes(guard);
  Object.assign(result, await verify?.());
  if (sample >= 0) results.push({case: key, sample, ...result, before, after});
}

async function crawl(workload, mode, sample) {
  const directory = path.join(root, 'crawl-' + configId++);
  const output = path.join(directory, 'output');
  await fs.mkdir(directory);
  const config = path.join(directory, 'options.mjs');
  await fs.writeFile(config, `
import {lifeCycle, options} from ${JSON.stringify(entry)};
export default options.defaultDownloadOptions({...lifeCycle.defaultLifeCycle(),
  localRoot: ${JSON.stringify(output)}, initialUrl: [], concurrency: 8, workerCount: 2,
  req: {retry: {limit: 0}}, createLogger: () => ({trace() {}, debug() {}, info() {},
    warn() {}, error() {}, isTraceEnabled: () => false})});
`);
  const expectedCount = workload === 'binary' ? 12 : documents;
  const admitted = [];
  await observed(`${mode}/${workload}`, sample, async () => {
    const started = performance.now();
    const crawler = new api.downloader[mode](pathToFileURL(config).href);
    let workers = [];
    try {
      await crawler.init;
      for (let id = 0; id < expectedCount; id++) {
        const binary = workload === 'binary';
        const url = `https://fixture.test/${id}.${binary ? 'bin' : 'html'}`;
        const res = api.resource.createResource({type: binary ? api.resource.ResourceType.Binary :
          api.resource.ResourceType.Html, depth: 0, url, refUrl: url, localRoot: output});
        const source = binary ? path.join(root, 'source.bin') :
          path.join(root, 'input', String(id), ...(workload === 'index-file' ? ['index.html'] : []));
        res.downloadLink = pathToFileURL(source).href;
        admitted.push(res);
        assert.equal(crawler.addProcessedResource(res), true);
      }
      await crawler.start();
      await crawler.onIdle();
      workers = crawler.pool?.workers.map(info => info.worker) ?? [];
    } finally { await crawler.dispose(); }
    const totalMs = performance.now() - started;
    return {totalMs, units: expectedCount, unit: 'resources/crawl', verify: async () => {
    assert.equal(crawler.downloadedCount, expectedCount);
    assert.equal(crawler.bufferedBytes, 0);
    assert.ok(workers.every(worker => worker.threadId === -1));
    assert.ok([...crawler.outcomes.values()].every(outcome => outcome.status === 'saved'));
    const files = (await fs.readdir(path.join(output, 'fixture.test'))).sort();
    assert.equal(files.length, expectedCount);
    const digest = createHash('sha256');
    for (const file of files) {
      const body = await fs.readFile(path.join(output, 'fixture.test', file));
      if (workload === 'binary') assert.deepEqual(body, bytes);
      else assert.ok(body.includes(`data-fixture="${parseInt(file)}"`));
      digest.update(file).update('\0').update(body);
    }
    if (workload !== 'binary' && (label === 'repair' || workload === 'index-file')) {
      for (let id = 0; id < admitted.length; id++) {
        assert.equal(admitted[id].meta.headers['content-length'], String(Buffer.byteLength(html(id))));
        assert.equal(admitted[id].meta.headers['last-modified'], new Date(1000000 * 1000).toISOString());
      }
    }
      return {sha256: digest.digest('hex')};
    }};
  });
  await fs.rm(directory, {recursive: true, force: true});
}

async function reads(workload, sample) {
  const resources = Array.from({length: readCount}, (_, id) => {
    const url = `https://fixture.test/${id}.html`;
    const res = api.resource.createResource({type: api.resource.ResourceType.Html,
      depth: 0, url, refUrl: url, localRoot: root, encoding: 'utf8'});
    res.downloadLink = pathToFileURL(path.join(root, 'input', String(id % documents),
      ...(workload === 'index-file' ? ['index.html'] : []))).href;
    return res;
  });
  await observed('acquire/' + workload, sample, async () => {
    const started = performance.now();
    for (const res of resources) await readOrCopyLocalResource(res, {}, {localRoot: root});
    const totalMs = performance.now() - started;
    return {totalMs, units: readCount, unit: 'sequential reads/batch', verify: () => {
      for (let id = 0; id < resources.length; id++) assert.equal(resources[id].body, html(id % documents));
    }};
  });
}

async function retries(kind, sample) {
  const retry = {attemptCount: 1, retryOptions: {limit: 5, methods: ['GET'], errorCodes: ['ETIMEDOUT'],
    statusCodes: [429]}, error: {name: kind === 'error' ? 'TimeoutError' : 'HTTPError',
    code: kind === 'error' ? 'ETIMEDOUT' : 'ERR_NON_2XX_3XX_RESPONSE', options: {method: 'GET'},
    response: kind === 'error' ? undefined : {statusCode: 429, headers: {'retry-after': '1'}}}};
  await observed('retry/' + kind, sample, async () => {
    const random = Math.random;
    let sum = 0;
    let totalMs;
    try {
      Math.random = () => 0.5;
      const started = performance.now();
      for (let id = 0; id < retryCount; id++) {
        retry.attemptCount = 1 + (id & 3);
        sum += api.options.calculateFastDelay(retry);
      }
      totalMs = performance.now() - started;
    } finally { Math.random = random; }
    assert.equal(sum, retryCount * (kind === 'error' ? 3050 : 1000));
    return {totalMs, units: retryCount, unit: 'retry calculations/batch'};
  });
}

try {
  await fs.writeFile(guard, Buffer.alloc(4096, 17));
  await fs.writeFile(path.join(root, 'source.bin'), bytes);
  for (let id = 0; id < documents; id++) {
    const directory = path.join(root, 'input', String(id));
    await fs.mkdir(directory, {recursive: true});
    const file = path.join(directory, 'index.html');
    await fs.writeFile(file, html(id));
    await fs.utimes(file, 1000000, 1000000);
    await fs.utimes(directory, 2000000, 2000000);
  }
  for (let id = 0; id < 5; id++) await probes(guard);
  for (const workload of ['binary', 'index-directory', 'index-file']) {
    for (const mode of ['SingleThreadDownloader', 'MultiThreadDownloader']) {
      for (let sample = -1; sample < samples; sample++) await crawl(workload, mode, sample);
    }
  }
  for (const workload of ['index-directory', 'index-file']) {
    for (let sample = -1; sample < samples; sample++) await reads(workload, sample);
  }
  for (const kind of ['error', 'retry-after']) {
    for (let sample = -1; sample < samples; sample++) await retries(kind, sample);
  }
  console.log(JSON.stringify({node: process.version, label, documents, readCount, retryCount, results}));
} finally { await fs.rm(root, {recursive: true, force: true}); }

