import assert from 'node:assert/strict';
import {promises as fs} from 'node:fs';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {probes} from './probes.mjs';

const root = fileURLToPath(new URL('./', import.meta.url));
const protocol = JSON.parse(await fs.readFile(root + 'protocol.json', 'utf8'));
const trees = JSON.parse(await fs.readFile(root + 'variants.json', 'utf8'));
const median = values => { const sorted = [...values].sort((a, b) => a - b); return (sorted[(sorted.length - 1) >> 1] + sorted[sorted.length >> 1]) / 2; };
assert.equal(process.version, protocol.node);
const guard = root + 'tmp/calibration.bin';
await fs.writeFile(guard, Buffer.alloc(4096, 17));
for (let id = 0; id < protocol.noise.calibrationWarmups; id++) await probes(guard);
const calibration = [];
for (let id = 0; id < protocol.noise.calibrationSamples; id++) calibration.push(await probes(guard));
const thresholds = Object.fromEntries(['cpuMs', 'ioMs'].map(key => [key, median(calibration.map(x => x[key])) * protocol.noise.thresholdMultiplier]));
const startedAt = new Date().toISOString();
await fs.writeFile(root + 'calibration.json', JSON.stringify({startedAt, calibration, thresholds}, null, 2));
const order = [], rows = [];
for (let round = 0; round < protocol.rounds; round++) {
  const sequence = [0, 1, 2]; sequence.push(...sequence.splice(0, round % 3));
  if (round % 2) sequence.reverse();
  order.push(sequence);
  for (const variant of sequence) {
    const label = protocol.variants[variant];
    const child = spawn(process.execPath, ['--expose-gc', root + 'bench.mjs', trees[label], label],
      {env: process.env, stdio: ['ignore', 'pipe', 'pipe']});
    let out = '', err = '';
    child.stdout.on('data', chunk => { out += chunk; }); child.stderr.on('data', chunk => { err += chunk; });
    const timer = setTimeout(() => child.kill('SIGTERM'), 120000);
    let code;
    try { code = await new Promise((resolve, reject) => { child.once('error', reject); child.once('close', resolve); }); }
    finally { clearTimeout(timer); }
    await fs.writeFile(root + `logs/round-${round}-${variant}.log`, err);
    assert.equal(code, 0, err);
    const data = JSON.parse(out);
    await fs.writeFile(root + `logs/round-${round}-${variant}.json`, out);
    assert.equal(data.results.length, 20);
    for (const result of data.results) rows.push({...result, round, variant});
    process.stderr.write(JSON.stringify({round, variant, finishedAt: new Date().toISOString()}) + '\n');
  }
}
function interval(values) {
  let state = protocol.statistics.bootstrapSeed;
  const random = () => { state ^= state << 13; state ^= state >>> 17; state ^= state << 5; return (state >>> 0) / 4294967296; };
  const samples = Array.from({length: protocol.statistics.bootstrapResamples}, () =>
    median(Array.from({length: values.length}, () => values[Math.floor(random() * values.length)]))).sort((a, b) => a - b);
  const quantile = p => { const at = p * (samples.length - 1), low = Math.floor(at); return samples[low] + (samples[Math.ceil(at)] - samples[low]) * (at - low); };
  return {median: median(values), interval95: [quantile(.025), quantile(.975)]};
}
const comparisons = [];
for (const key of new Set(rows.map(row => row.case))) {
  const samples = rows.filter(row => row.case === key);
  assert.equal(samples.length, protocol.rounds * 3 * protocol.samplesPerProcess);
  if (samples[0].sha256) assert.equal(new Set(samples.map(x => x.sha256)).size, 1);
  const failures = samples.flatMap(x => ['before', 'after'].flatMap(when => ['cpuMs', 'ioMs']
    .filter(metric => x[when][metric] > thresholds[metric])
    .map(metric => ({round: x.round, variant: x.variant, sample: x.sample, when, metric, value: x[when][metric]}))));
  const excluded = [...new Set(failures.map(x => x.round))].sort((a, b) => a - b);
  const included = Array.from({length: protocol.rounds}, (_, id) => id).filter(id => !excluded.includes(id));
  const result = {case: key, units: samples[0].units, unit: samples[0].unit, acceptedRounds: included.length,
    excludedRounds: excluded, noiseFailures: failures, samples, status: 'inconclusive-insufficient-rounds'};
  if (included.length >= protocol.minimumQualifyingRounds) {
    const medians = included.map(round => [0, 1, 2].map(variant => median(samples.filter(x => x.round === round && x.variant === variant).map(x => x.totalMs))));
    result.processMedians = medians;
    result.medianMs = [0, 1, 2].map(variant => median(medians.map(x => x[variant])));
    result.controlPercent = interval(medians.map(x => 100 * (x[1] / x[0] - 1)));
    result.repairVsBaselinePercent = interval(medians.map(x => 100 * (x[2] / x[0] - 1)));
    result.repairVsControlPercent = interval(medians.map(x => 100 * (x[2] / x[1] - 1)));
    result.repairVsBaselineMs = interval(medians.map(x => x[2] - x[0]));
    result.repairVsControlMs = interval(medians.map(x => x[2] - x[1]));
    const [low, high] = result.controlPercent.interval95;
    result.controlPass = low <= 0 && high >= 0 && low >= -5 && high <= 5;
    result.status = !result.controlPass ? 'inconclusive-control' :
      result.repairVsBaselinePercent.interval95[1] <= 0 && result.repairVsControlPercent.interval95[1] <= 0 ? 'pass' : 'not-passed';
  }
  comparisons.push(result);
}
console.log(JSON.stringify({startedAt, finishedAt: new Date().toISOString(), protocol, calibration, thresholds, order,
  comparisons, allFocusedCasesPass: comparisons.every(x => x.status === 'pass')}, null, 2));

